<script>
 import { onMount, tick } from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import { consoleSession, consoleAvailability, consoleRows } from './console-state.js';
 import { validConsoleFeed, consoleSources } from './console-feed.js';
 import { consoleMenus } from './console-menus.js';
 import { createConsoleNativeView } from './console-native-view.js';
 import './console.css';
 let {state: consoleState,session:providedSession=null,window:actualWindow=null,windowId=actualWindow?.id,profile,controller,oncommand=null,execute=null,registerView=null,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state(''),searchName=$state(''),exportName=$state('Scene Events'),exportFormat=$state('json'),exportScope=$state('visible');
 let originalState,originalProfile,originalWindow,originalWindowId,originalController,originalSession,retired=false;
 const session=$derived(providedSession??consoleSession(consoleState,windowId)),cap=$derived(consoleAvailability(profile));
 const inventory=$derived(controller?.getInventory?.()),rawFeed=$derived(controller?.getSceneEvents?.()),feed=$derived(validConsoleFeed(rawFeed)?rawFeed:null);
 const rows=$derived(consoleRows(feed,session)),sources=$derived(inventory&&feed?consoleSources(inventory,feed):[]),selected=$derived(rows.find(event=>event.id===session?.selectedId)??null),menus=$derived(consoleMenus(profile,consoleState,windowId,feed));
 const time=value=>new Date(value).toLocaleTimeString('en-US',{hour12:false,timeZone:'UTC',hour:'2-digit',minute:'2-digit',second:'2-digit'})+'.'+String(new Date(value).getUTCMilliseconds()).padStart(3,'0');
 const sourceName=event=>event.sourceAppId?(profile.applications[event.sourceAppId]?.name??event.sourceAppId):'Scene';
 function owned(){return !retired&&root?.isConnected===true&&consoleState===originalState&&profile===originalProfile&&actualWindow===originalWindow&&windowId===originalWindowId&&controller===originalController&&session===originalSession;}
 async function dispatch(command,target,payload){const runner=oncommand??execute;if(runner)return await runner(command,target,payload);return await controller?.handlers?.[command]?.(target,payload);}
 async function command(name,payload={}){if(!owned()||!available||!active)return;const result=await dispatch(`console.${name}`,{windowId},payload);if(owned())message=result?.status==='applied'?'':result?.error?.message??'Local scene operation unavailable.';return result;}
 const filter=patch=>command('filter',{filter:{...session.filter,...patch}});
 function key(event){if(!owned()||!available||!active)return;if(event.key==='Escape'){command('menu',{menuId:null});command('panel',{panel:'none'});}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='f'){event.preventDefault();root.querySelector('[data-console-control="search"]')?.focus();}if(event.key==='Enter'&&event.target.dataset.consoleEvent)command('inspect',{eventId:event.target.dataset.consoleEvent});}
 async function menuItem(item){if(!item.enabled)return;await command('menu',{menuId:null});if(owned())await dispatch(item.command,item.target,item.payload);}
 async function close(){if(!owned()||!available||!active)return;if(controls.onclose)return controls.onclose();return dispatch('window.close',{windowId},{});}
 async function doExport(){const extension=exportFormat==='text'?'log':exportFormat==='report'?'event-report.txt':'json';return command('export',{format:exportFormat,scope:exportScope,name:`${exportName.replace(/\.(json|log|event-report\.txt)$/u,'')}.${extension}`});}
 onMount(()=>{originalState=consoleState;originalProfile=profile;originalWindow=actualWindow;originalWindowId=windowId;originalController=controller;originalSession=session;const view=createConsoleNativeView({getRoot:()=>root,getState:()=>consoleState,getSession:()=>session,getProfile:()=>profile,getWindow:()=>actualWindow,getController:()=>controller,windowId,available:()=>owned()&&available&&active,tick,getMenus:()=>consoleMenus(profile,consoleState,windowId,feed)});registerView?.(windowId,view);return()=>{retired=true;view.destroy();registerView?.(originalWindowId,null,view);};});
</script>
<section bind:this={root} class="console-app" class:windows={cap.windows} class:legacy={cap.legacy} class:golden={cap.golden} class:inactive={!active} data-console-window-id={windowId} data-profile={profile.id} role="region" aria-label={cap.label} tabindex="-1" onkeydown={key}>
 <header class="console-titlebar">
  {#if !cap.windows}<WindowControls active={active} onclose={close} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
  <strong>{cap.label}</strong><span>{inventory?.system?.computerName??'Scene event feed unavailable'}</span>
 </header>
 <nav class="console-menus" aria-label="Application menus">{#each menus as menu}<button data-console-control={`menu:${menu.id}`} aria-haspopup="menu" aria-expanded={session?.menu===menu.id} disabled={!available||!active} onclick={()=>command('menu',{menuId:session?.menu===menu.id?null:menu.id})}>{menu.label}</button>{/each}</nav>
 {#if session?.menu}<div class="console-menu-popup" role="menu" aria-label={menus.find(m=>m.id===session.menu)?.label}>{#each menus.find(m=>m.id===session.menu)?.items??[] as item}<button role="menuitem" disabled={!item.enabled} data-console-control={`menuitem:${item.id}`} onclick={()=>menuItem(item)}><span>{item.checked?'✓':''}</span>{item.label}</button>{/each}{#if session.menu==='action'&&!consoleState.savedSearches.length}<span class="console-empty-menu">No saved searches</span>{/if}</div>{/if}
 <div class="console-toolbar">
  <button data-console-control="stream" disabled={!feed||!available||!active} onclick={()=>command('stream',{streaming:!session.streaming})}><b>{session?.streaming?'Ⅱ':'▶'}</b><span>{session?.streaming?'Pause':cap.legacy?'Resume':'Start'}</span></button>
  <button data-console-control="clear" disabled={!rows.length||!available||!active} onclick={()=>command('clear')}><b>⌫</b><span>Clear</span></button>
  <button data-console-control="inspect" disabled={!selected||!available||!active} onclick={()=>command('inspect')}><b>ⓘ</b><span>{cap.windows?'Properties':'Info'}</span></button>
  <button data-console-control="export" disabled={!rows.length||!available||!active} onclick={()=>command('panel',{panel:'export'})}><b>↥</b><span>Export</span></button>
  <label class="console-search"><span>⌕</span><input data-console-control="search" type="search" aria-label="Search actual scene events" placeholder={cap.windows?'Find local events':'Search'} maxlength="4096" value={session?.filter.query??''} disabled={!feed||!available||!active} oninput={event=>filter({query:event.currentTarget.value})}/></label>
  <button class="console-save-search" data-console-control="save-search" disabled={!available||!active} onclick={()=>command('panel',{panel:'save-search'})}>{cap.windows?'Create Custom View…':'Save'}</button>
 </div>
 <div class="console-favorites" inert={!available||!active||session?.panel!=='none'}><button class:chosen={session?.filter.category==='all'&&session?.filter.severity==='all'} data-console-control="all" onclick={()=>filter({category:'all',severity:'all'})}>{cap.windows?'All Local Events':'All Messages'}</button><button class:chosen={session?.filter.severity==='error'} data-console-control="errors" onclick={()=>filter({severity:'error'})}>Errors</button><select data-console-control="severity" aria-label="Event severity" value={session?.filter.severity??'all'} onchange={event=>filter({severity:event.currentTarget.value})}><option value="all">All levels</option>{#each ['info','warning','error'] as level}<option value={level}>{level[0].toUpperCase()+level.slice(1)}</option>{/each}</select>{#each consoleState.savedSearches as saved}<button data-console-control={`saved:${saved.id}`} onclick={()=>command('search.apply',{searchId:saved.id})}>{saved.name}</button>{/each}</div>
 <div class="console-workspace" inert={!available||!active||session?.panel!=='none'}>
  {#if consoleState.preferences.sidebar}<aside class="console-sidebar" data-console-area="sidebar"><h2>{cap.windows?'Event Viewer (Local)':'Devices'}</h2><button data-console-control="device" class:chosen={!session?.sourceId} onclick={()=>command('device',{deviceId:profile.id})}>▣ {inventory?.system?.computerName??'Unavailable'}</button><h2>{cap.windows?'Applications and Services':'Sources'}</h2><button data-console-control="source:all" class:chosen={!session?.sourceId} onclick={()=>command('source',{sourceId:null})}>All actual sources</button>{#each sources as source}<button data-console-control={`source:${source.id}`} class:chosen={session?.sourceId===source.id} onclick={()=>command('source',{sourceId:source.id})}>▤ {source.name}</button>{/each}<h2>Reports</h2><button data-console-control="reports" class:chosen={session?.filter.category==='reports'} onclick={()=>filter({category:'reports'})}>▧ Action Failure Reports</button><button data-console-control="crashes" class:chosen={session?.filter.category==='crashes'} onclick={()=>filter({category:'crashes'})}>▧ Crash Reports</button><p>Only this scene’s actual operations. No connected or remote devices.</p></aside>{/if}
  <main class="console-main"><div class="console-log-heading"><strong>{session?.filter.category==='crashes'?'Crash Reports':session?.filter.category==='reports'?'Action Failure Reports':cap.windows?'Local Scene Events':'Messages'}</strong><span>{rows.length} {rows.length===1?'event':'events'} · {session?.streaming?'Streaming':'Paused'}</span></div>
   <div class="console-events" data-console-area="events"><table><thead><tr><th>{cap.windows?'Level':'Type'}</th><th>Time (UTC)</th><th>{cap.windows?'Source':'Process'}</th><th>{cap.windows?'Event':'Message'}</th><th>Status</th></tr></thead><tbody>{#each rows as event (event.id)}<tr class:selected={selected===event}><td><span class="console-severity" class:error={event.severity==='error'} class:warning={event.severity==='warning'} aria-label={event.severity}>●</span></td><td>{time(event.time)}</td><td>{sourceName(event)}</td><td><button data-console-event={event.id} data-console-control={`event:${event.id}`} onclick={()=>command('select',{eventId:event.id})} ondblclick={()=>command('inspect',{eventId:event.id})}>{event.command}</button></td><td>{event.status}</td></tr>{/each}</tbody></table>
    {#if !feed}<div class="console-empty"><strong>Event feed unavailable</strong><p>The original Root event feed must be mounted; no demonstration events are generated.</p></div>{:else if !rows.length}<div class="console-empty"><strong>{session?.filter.category==='crashes'?'No crash reports':session?.streaming?'No matching local events':'Click Start to view events'}</strong><p>{session?.filter.category==='crashes'?'This scene has no native crash collector. Force quit and rejected commands are not reported as crashes.':session?.filter.category==='reports'?'Reports are derived from actual rejected action events; no historical reports are simulated.':session?.clearThrough?'Display cleared only in this window. The shared source feed was not deleted.':'Run scene operations, resume streaming or change the filter.'}</p></div>{/if}
   </div>
   {#if consoleState.preferences.showInfo}<section class="console-detail" data-console-area="detail" aria-label="Event details">{#if selected}<h2>{selected.command}</h2><dl><dt>Event ID</dt><dd>{selected.id}</dd><dt>Timestamp</dt><dd>{new Date(selected.time).toISOString()}</dd><dt>Source</dt><dd>{sourceName(selected)}</dd><dt>Window</dt><dd>{selected.sourceWindowId??'No source window'}</dd><dt>Severity</dt><dd>{selected.severity}</dd><dt>Result</dt><dd>{selected.status}</dd></dl><pre>{JSON.stringify(selected,null,2)}</pre>{:else}<p>Select an actual event to inspect its original action metadata.</p>{/if}</section>{/if}
  </main>
  {#if cap.windows}<aside class="console-actions"><h2>Actions</h2><button data-console-control="action:export" disabled={!rows.length} onclick={()=>command('panel',{panel:'export'})}>Save All Events As…</button><button data-console-control="action:clear" disabled={!rows.length} onclick={()=>command('clear')}>Clear This View</button><button data-console-control="action:custom" onclick={()=>command('panel',{panel:'save-search'})}>Create Custom View…</button><h2>Selected Event</h2><button data-console-control="action:inspect" disabled={!selected} onclick={()=>command('inspect')}>Event Properties</button><button data-console-control="action:report" disabled={!selected} onclick={()=>command('export',{format:'report',scope:'selected'})}>Save Selected Event…</button></aside>{/if}
 </div>
 {#if session?.panel!=='none'}<div class="console-sheet-backdrop"><section class="console-sheet" role="dialog" aria-modal="true" aria-label={session?.panel==='save-search'?'Save Search':session?.panel==='export'?'Export Events':session?.panel==='preferences'?'Console Preferences':'Console Help'}>
  {#if session?.panel==='save-search'}<h2>{cap.windows?'Create Custom View':'Save Search'}</h2><p>Save the current text, severity and report filter. Event data is never saved with a search.</p><label>Name <input data-console-control="search-name" maxlength="128" bind:value={searchName}/></label><div class="console-sheet-buttons"><button data-console-control="save-search:cancel" onclick={()=>command('panel',{panel:'none'})}>Cancel</button><button data-console-control="save-search:save" disabled={!searchName.trim()} onclick={()=>command('search.save',{name:searchName})}>Save</button></div>
  {:else if session?.panel==='export'}<h2>Export Local Scene Events</h2><p>Exports an immutable snapshot of original events into shared Documents. No fake .evtx, .ips or .logarchive files.</p><label>Name <input data-console-control="export-name" maxlength="220" bind:value={exportName}/></label><label>Format <select data-console-control="export-format" bind:value={exportFormat}><option value="json">JSON event data (.json)</option><option value="text">Tab-separated text (.log)</option><option value="report">Readable event report (.event-report.txt)</option></select></label><label>Events <select data-console-control="export-scope" bind:value={exportScope}><option value="visible">All visible ({rows.length})</option><option value="selected" disabled={!selected}>Selected event</option></select></label><div class="console-sheet-buttons"><button data-console-control="export:cancel" onclick={()=>command('panel',{panel:'none'})}>Cancel</button><button data-console-control="export:save" disabled={!exportName.trim()||!rows.length||exportScope==='selected'&&!selected} onclick={doExport}>Export</button></div>
  {:else if session?.panel==='preferences'}<h2>{cap.legacy?'Preferences':'Settings'}</h2><label><input type="checkbox" data-console-control="preferences:sidebar" checked={consoleState.preferences.sidebar} onchange={event=>command('preferences',{values:{...consoleState.preferences,sidebar:event.currentTarget.checked}})}/> Show sidebar</label><label><input type="checkbox" data-console-control="preferences:info" checked={consoleState.preferences.showInfo} onchange={event=>command('preferences',{values:{...consoleState.preferences,showInfo:event.currentTarget.checked}})}/> Show event details</label><p>Saved searches and filter preferences persist. The Root event feed is transient; no event copies are retained in app state.</p><button data-console-control="preferences:done" onclick={()=>command('panel',{panel:'none'})}>Done</button>
  {:else}<h2>{cap.label} — Local Scene Events</h2><p>{cap.disclosure}</p><p>Search actual command names, source application IDs, statuses and event IDs. Pause captures a monotonic event cursor; older events can expire when the bounded Root feed rotates. Clear only advances this window’s cursor.</p><p>Action Failure Reports derive from rejected operations. Native crash reports, historical logs, analytics, host process traces, remote devices, log archive import and EVTX parsing are unavailable.</p><button data-console-control="help:done" onclick={()=>command('panel',{panel:'none'})}>Done</button>{/if}
  {#if message}<p class="console-error" role="alert">{message}</p>{/if}
 </section></div>{/if}
 <footer class="console-status" role="status"><span>{message||cap.disclosure}</span><span>{session?.streaming?'Live':'Paused'} · {rows.length}</span></footer>
</section>
